files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #edf2f4;
  --muted: #8d99ae;
  --work: #e94560;
  --break: #4ecdc4;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: 'Courier New', Courier, monospace;
  font-size: 16px;
  padding: 16px;
  color: var(--text);
}

.card {
  background: var(--card);
  border: 4px solid var(--accent);
  border-radius: 0;
  padding: 32px 24px;
  max-width: 420px;
  width: 100%;
  text-align: center;
  box-shadow: 8px 8px 0 rgba(0, 0, 0, 0.4);
}

.title {
  font-size: 1.25rem;
  letter-spacing: 4px;
  color: var(--accent);
  margin-bottom: 16px;
}

.mode-indicator {
  font-size: 0.9rem;
  letter-spacing: 3px;
  color: var(--muted);
  margin-bottom: 8px;
  text-transform: uppercase;
}

.mode-indicator .break {
  color: var(--break);
}

.timer {
  font-size: clamp(3rem, 18vw, 5rem);
  font-weight: bold;
  letter-spacing: 4px;
  color: var(--text);
  margin: 8px 0 24px;
  line-height: 1.1;
  font-variant-numeric: tabular-nums;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  margin-bottom: 16px;
  flex-wrap: wrap;
}

button {
  font-family: inherit;
  font-size: 1rem;
  font-weight: bold;
  letter-spacing: 2px;
  padding: 12px 20px;
  border: 3px solid var(--text);
  background: transparent;
  color: var(--text);
  cursor: pointer;
  transition: background 0.1s, color 0.1s, transform 0.05s;
}

button:hover {
  background: var(--text);
  color: var(--card);
}

button:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 3px;
}

button:active {
  transform: translate(2px, 2px);
}

button.active {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--text);
}

button.active:hover {
  background: var(--accent);
  color: var(--text);
}

.mode-switch {
  display: flex;
  gap: 12px;
  justify-content: center;
  margin-bottom: 16px;
}

.mode-switch button {
  font-size: 0.85rem;
  padding: 8px 16px;
  border-width: 2px;
}

.hint {
  font-size: 0.75rem;
  color: var(--muted);
  letter-spacing: 1px;
  margin-top: 8px;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  .controls {
    flex-direction: column;
  }
  .controls button {
    width: 100%;
  }
}

(function () {
  'use strict';

  const WORK_SECONDS = 25 * 60;
  const BREAK_SECONDS = 5 * 60;

  const timerEl = document.getElementById('timer');
  const modeLabel = document.getElementById('modeLabel');
  const startPauseBtn = document.getElementById('startPauseBtn');
  const resetBtn = document.getElementById('resetBtn');
  const workModeBtn = document.getElementById('workModeBtn');
  const breakModeBtn = document.getElementById('breakModeBtn');

  let mode = 'work';
  let remaining = WORK_SECONDS;
  let running = false;
  let intervalId = null;
  let lastTick = 0;

  function formatTime(totalSeconds) {
    const m = Math.floor(totalSeconds / 60);
    const s = totalSeconds % 60;
    return String(m).padStart(2, '0') + ':' + String(s).padStart(2, '0');
  }

  function render() {
    timerEl.textContent = formatTime(remaining);
    startPauseBtn.textContent = running ? 'PAUSE' : 'START';
    startPauseBtn.setAttribute('aria-label', running ? 'Pause timer' : 'Start timer');

    if (mode === 'work') {
      modeLabel.textContent = 'WORK';
      modeLabel.classList.remove('break');
    } else {
      modeLabel.textContent = 'BREAK';
      modeLabel.classList.add('break');
    }

    workModeBtn.classList.toggle('active', mode === 'work');
    breakModeBtn.classList.toggle('active', mode === 'break');
  }

  function stopInterval() {
    if (intervalId !== null) {
      clearInterval(intervalId);
      intervalId = null;
    }
  }

  function tick() {
    const now = Date.now();
    const delta = Math.floor((now - lastTick) / 1000);
    if (delta <= 0) return;
    lastTick += delta * 1000;
    remaining = Math.max(0, remaining - delta);
    render();
    if (remaining === 0) {
      stopInterval();
      running = false;
      render();
    }
  }

  function start() {
    if (running || remaining === 0) return;
    running = true;
    lastTick = Date.now();
    intervalId = setInterval(tick, 250);
    render();
  }

  function pause() {
    if (!running) return;
    running = false;
    stopInterval();
    render();
  }

  function reset() {
    running = false;
    stopInterval();
    remaining = mode === 'work' ? WORK_SECONDS : BREAK_SECONDS;
    render();
  }

  function setMode(newMode) {
    mode = newMode;
    reset();
  }

  startPauseBtn.addEventListener('click', function () {
    if (running) {
      pause();
    } else {
      start();
    }
  });

  resetBtn.addEventListener('click', reset);

  workModeBtn.addEventListener('click', function () {
    setMode('work');
  });

  breakModeBtn.addEventListener('click', function () {
    setMode('break');
  });

  document.addEventListener('keydown', function (e) {
    if (e.target.tagName === 'BUTTON' && e.key === ' ') return;
    if (e.key === ' ') {
      e.preventDefault();
      if (running) pause(); else start();
    } else if (e.key === 'r' || e.key === 'R') {
      reset();
    } else if (e.key === 'w' || e.key === 'W') {
      setMode('work');
    } else if (e.key === 'b' || e.key === 'B') {
      setMode('break');
    }
  });

  render();
})();
